insert into public.bmo_sop_catalogo (id, versao, etapa_num, etapa_nome, workflow, ordem, sequencia, tarefa, descricao, papel_responsavel, tipo, prazo_padrao, prioridade, gate, skill_vinculada, sem_ini, sem_fim, pop, checklist) values
  ('E01-T01', 'v8.0-pop-20261103', 1, 'Kick-off', 'Implementação', 1, 1, 'Registro do "Ganho" no CRM', 'Ao fechar a venda, o Vendedor registra a oportunidade como "Ganho" no CRM. É o marco formal de entrada do cliente e o gatilho para o Diretor definir o squad.', 'Vendedor', 'Manual', 'Dia 0', 'P1', 'Oportunidade registrada como "Ganho" no CRM.', null, 0, 0.5, '{"obj": "Formalizar a entrada do cliente e disparar a definição do squad.", "ent": ["Contrato assinado", "Proposta aceita"], "passos": ["Conferir que contrato e proposta estão assinados e aceitos.", "Abrir a oportunidade no CRM e mudar o estágio para \"Ganho\".", "Registrar valor de implementação e MRR conforme proposta.", "Avisar o Diretor que o cliente está pronto para definição do squad."], "sai": "Oportunidade em \"Ganho\" no CRM.", "ferr": ["CRM"], "cuid": ["Sem \"Ganho\" registrado, o squad não é definido — é o marco formal do Dia 0."], "pend": ["Nome do CRM e campos obrigatórios da oportunidade não constam nas fontes."]}'::jsonb, null),
  ('E01-T02', 'v8.0-pop-20261103', 1, 'Kick-off', 'Implementação', 2, 2, 'Definição do squad', 'Com o "Ganho" registrado no CRM, o Diretor designa formalmente qual squad atenderá o cliente, considerando carga de carteira e perfil da clínica. Conclui quando o squad está registrado no sistema interno.', 'Diretor', 'Manual', 'Dia 0', 'P1', 'Squad definido e registrado no sistema.', null, 0, 0.5, '{"obj": "Designar o squad que atenderá o cliente.", "ent": ["\"Ganho\" no CRM", "Carga atual de cada squad", "Perfil da clínica"], "passos": ["Verificar a carga de carteira de cada squad (meta: 30 clientes por squad).", "Avaliar o perfil da clínica (especialidade, porte, complexidade).", "Designar o squad e registrá-lo no sistema interno.", "Comunicar o Vendedor e o Gerente de Contas do squad escolhido."], "sai": "Squad registrado no sistema interno.", "ferr": ["Sistema interno BMO"], "cuid": ["Registrar o squad antes do cadastro (E01-T03) — o cadastro exige o campo Squad."]}'::jsonb, null),
  ('E01-T03', 'v8.0-pop-20261103', 1, 'Kick-off', 'Implementação', 3, 3, 'Criação do perfil, acesso e cadastro do cliente no sistema interno', 'Com o squad definido, o Vendedor cria o perfil e o acesso do cliente no sistema interno e preenche o cadastro completo, aproveitando os dados já coletados para o contrato (CNPJ, razão social, endereço com CEP, nome completo e e-mail do responsável). Sem este cadastro, nenhuma etapa seguinte é liberada.', 'Vendedor', 'Manual', 'Dia 0', 'P1', 'Perfil e acesso criados + cadastro completo no sistema.', null, 0, 0.5, '{"obj": "Criar perfil, acesso e cadastro completo do cliente.", "ent": ["Dados do contrato: CNPJ, razão social, endereço com CEP, nome e e-mail do responsável", "Squad definido"], "passos": ["Acessar /client/new no sistema interno.", "Preencher Nome, Squad, Status, Segmento, Produto, Cidade/UF, Dia do Pagamento, Data de início, Implementação (R$), MRR e Template \"padrão\".", "Criar as credenciais no Pricer no padrão clinica.nome com a senha de 1º acesso (Manual de Boas Práticas, Fase 2).", "Ativar \"Exibir formulário de onboarding para esta clínica\" e validar em \"Acessar Pricer\".", "Conferir que o cadastro redireciona para a visão do Squad."], "sai": "Perfil, acesso e cadastro completos no sistema.", "ferr": ["Sistema interno (bmo-interno.onrender.com)", "Pricer (app.bmogestao.com.br)"], "cuid": ["Login em minúsculas, sem espaço ou acento.", "Campo Cidade/UF exige seleção da opção listada; se não existir, criar pelo botão \"+\"."]}'::jsonb, null),
  ('E01-T04', 'v8.0-pop-20261103', 1, 'Kick-off', 'Implementação', 4, 4, 'Anexo e conferência dos documentos de fechamento', 'O Vendedor anexa ao cadastro os três documentos de fechamento: Comprovante de Pagamento, Contrato Assinado e Relatório de Fechamento. Cada documento recebe um check de conferência, dado pelo Vendedor e/ou pelo Gerente de Contas (checklist na aba BD_Checklists).', 'Vendedor', 'Manual', 'Dia 0', 'P1', '3 documentos anexados, cada um com check de conferência (Vendedor e/ou Gerente de Contas).', null, 0, 0.5, '{"obj": "Anexar e conferir os três documentos de fechamento.", "ent": ["Comprovante de Pagamento", "Contrato Assinado", "Relatório de Fechamento"], "passos": ["Anexar os três documentos ao cadastro do cliente.", "Marcar o check de conferência de cada documento (Vendedor e/ou GC) no Controle por cliente.", "Liberar a Etapa 2 somente com os 3 itens conferidos."], "sai": "3 documentos anexados e conferidos (CHK-E01-T04-01 a 03).", "ferr": ["Sistema interno", "Painel — Controle por cliente"], "cuid": ["Regra de conclusão: basta um dos dois checks por documento (Vendedor ou GC)."]}'::jsonb, '[{"id": "CHK-E01-T04-01", "item": "Comprovante de Pagamento", "obrig": "Obrigatório", "uso": "Formalização do contrato; libera a Etapa 2", "periodo": "—", "resp": "Vendedor", "l1": "Conferido — Vendedor", "l2": "Conferido — Gerente de Contas"}, {"id": "CHK-E01-T04-02", "item": "Contrato Assinado", "obrig": "Obrigatório", "uso": "Formalização do contrato; libera a Etapa 2", "periodo": "—", "resp": "Vendedor", "l1": "Conferido — Vendedor", "l2": "Conferido — Gerente de Contas"}, {"id": "CHK-E01-T04-03", "item": "Relatório de Fechamento", "obrig": "Obrigatório", "uso": "Formalização do contrato; libera a Etapa 2", "periodo": "—", "resp": "Vendedor", "l1": "Conferido — Vendedor", "l2": "Conferido — Gerente de Contas"}]'::jsonb),
  ('E01-T05', 'v8.0-pop-20261103', 1, 'Kick-off', 'Implementação', 5, 5, 'Criação do grupo, boas-vindas e envio do acesso ao Formulário', 'Concluído o cadastro com os documentos, o Vendedor cria o grupo de WhatsApp do cliente no padrão "Gestão <> bmo & [Cliente]" (ou reaproveita o grupo já criado na negociação) e adiciona os integrantes do squad designado. Envia a mensagem padrão de boas-vindas apresentando o squad e o papel de cada um e, em seguida, o acesso à Área do Cliente BMO (link, usuário e senha) com as instruções do Formulário de diagnóstico: preencher com calma, de preferência no computador, com o máximo de detalhes, e clicar em Enviar.', 'Vendedor', 'Manual', 'Dia 0', 'P1', 'Grupo criado com o squad completo + boas-vindas com apresentação do time + acesso à Área do Cliente e instruções do Formulário enviados.', null, 0, 0.5, '{"obj": "Criar o grupo, apresentar o squad e enviar o acesso ao Formulário.", "ent": ["Cadastro concluído", "Credenciais da Área do Cliente", "Integrantes do squad"], "passos": ["Criar o grupo de WhatsApp \"Gestão <> bmo & [Cliente]\" ou reaproveitar o da negociação.", "Adicionar os integrantes do squad.", "Enviar a mensagem padrão de boas-vindas apresentando o squad e o papel de cada um (termo oficial: Analista de Negócios).", "Enviar link app.bmogestao.com.br/Pricer-bmo, login e senha.", "Orientar o Formulário: preencher com calma, no computador, com o máximo de detalhes, e clicar em Enviar."], "sai": "Grupo com squad completo + boas-vindas + acesso e instruções enviados.", "ferr": ["WhatsApp Business", "Pricer / Área do Cliente"], "cuid": ["Conferir o acesso em \"Acessar Pricer\" antes do envio para não mandar credencial errada."], "pend": ["Texto padrão da mensagem de boas-vindas do Vendedor não localizado no Projeto."]}'::jsonb, null),
  ('E01-T06', 'v8.0-pop-20261103', 1, 'Kick-off', 'Implementação', 6, 6, 'Boas-vindas do Gerente de Contas e reforço do Formulário', 'No mesmo dia, o Gerente de Contas envia no grupo sua mensagem de boas-vindas, se apresenta como responsável pelo acompanhamento junto ao time de execução e reforça que, com o Formulário enviado, o squad agenda a reunião de onboarding (conforme a data de preferência informada) e solicita os primeiros documentos.', 'Gerente de Contas', 'Manual', 'Dia 0', 'P1', 'Boas-vindas do Gerente de Contas enviadas no grupo no mesmo dia das boas-vindas do Vendedor.', null, 0, 0.5, '{"obj": "Apresentar o Gerente de Contas e reforçar o Formulário.", "ent": ["Boas-vindas do Vendedor enviadas"], "passos": ["No mesmo dia, enviar a mensagem de boas-vindas do GC no grupo.", "Apresentar-se como responsável pelo acompanhamento junto ao time de execução.", "Reforçar que, com o Formulário enviado, o squad agenda o onboarding na data de preferência e solicita os primeiros documentos."], "sai": "Boas-vindas do GC no grupo, no mesmo dia das do Vendedor.", "ferr": ["WhatsApp Business"], "pend": ["Texto padrão da mensagem do GC não localizado no Projeto."]}'::jsonb, null),
  ('E01-T07', 'v8.0-pop-20261103', 1, 'Kick-off', 'Implementação', 7, 7, 'Acompanhamento até o envio do Formulário de diagnóstico', 'O Vendedor pede ao cliente que confirme no grupo quando enviar o Formulário e acompanha até o envio, incluindo a data de preferência para a reunião de onboarding. O Gerente de Contas confirma o recebimento pelo aviso do sistema. Com o envio confirmado, o Vendedor sinaliza no grupo a passagem para o squad, que agenda o onboarding — fim do Kick-off e início da Etapa 2.', 'Vendedor + Gerente de Contas', 'Manual', 'Até o envio do Formulário', 'P1', 'Formulário enviado + recebimento confirmado pelo GC (aviso do sistema) + passagem para o squad sinalizada no grupo.', null, 0, 0.5, '{"obj": "Acompanhar até o envio do Formulário e passar o cliente ao squad.", "ent": ["Formulário liberado", "Grupo ativo"], "passos": ["Pedir ao cliente que confirme no grupo quando enviar o Formulário.", "Acompanhar até o envio, incluindo a data de preferência para o onboarding.", "GC confirma o recebimento pelo aviso do sistema.", "Vendedor sinaliza no grupo a passagem para o squad — fim do Kick-off."], "sai": "Formulário enviado, recebimento confirmado e passagem sinalizada.", "ferr": ["Sistema interno (aviso de Formulário)", "WhatsApp"], "cuid": ["Não iniciar a Etapa 2 sem a confirmação do GC pelo sistema."], "pend": ["Prazo máximo de cobrança do Formulário não definido nas fontes."]}'::jsonb, null),
  ('E02-T01', 'v8.0-pop-20261103', 2, 'Onboarding e Diagnóstico', 'Implementação', 1, 8, 'Leitura do formulário e identificação da data de preferência para a reunião', 'O Gerente de Contas analisa as respostas do Formulário de diagnóstico, extrai os pontos críticos e identifica a data e o horário de preferência informados pelo cliente para a reunião de onboarding.', 'Gerente de Contas', 'Manual', 'Dia 1', 'P1', 'Análise concluída + data de preferência identificada.', 'Fase0-Prompt-Abertura-Briefing-Estrategico.md', 0.5, 1.5, '{"obj": "Extrair do Formulário os pontos críticos e a data preferida da reunião.", "ent": ["Formulário de diagnóstico enviado"], "passos": ["Ler as respostas do Formulário na Área do Cliente.", "Listar os pontos críticos (dores, metas, sistemas usados, estrutura).", "Identificar data e horário de preferência para o onboarding.", "Abrir o Projeto Claude do cliente (\"BMO × [Clínica]\") e registrar os achados."], "sai": "Análise concluída + data de preferência identificada.", "ferr": ["Área do Cliente", "Claude (Projeto do cliente)"]}'::jsonb, null),
  ('E02-T02', 'v8.0-pop-20261103', 2, 'Onboarding e Diagnóstico', 'Implementação', 2, 9, 'Agendamento da reunião de onboarding', 'O GC agenda a reunião com o cliente na janela identificada e confirma a presença dos participantes necessários (decisor + squad).', 'Gerente de Contas', 'Manual', 'Dia 1', 'P1', 'Reunião agendada e confirmada.', 'Fase0-Prompt-Abertura-Briefing-Estrategico.md', 0.5, 1.5, '{"obj": "Agendar a reunião de onboarding com decisor e squad.", "ent": ["Data de preferência", "Agenda do squad"], "passos": ["Consultar conflitos na agenda.", "Criar o evento \"[Cliente] & BMO <> Onboarding\" com Google Meet, duração padrão de 1 hora.", "Convidar o decisor e o squad.", "Confirmar a presença no grupo do cliente."], "sai": "Reunião agendada e confirmada.", "ferr": ["Google Calendar", "WhatsApp"], "cuid": ["Data sem horário confirmado não é agendada — aguardar a confirmação."]}'::jsonb, null),
  ('E02-T03', 'v8.0-pop-20261103', 2, 'Onboarding e Diagnóstico', 'Implementação', 3, 10, 'Envio da lista de coleta de dados (Checklist de Coleta)', 'Logo após a reunião de onboarding, envia no grupo a lista de dados e documentos alinhada na reunião, a partir do Checklist de Coleta (aba BD_Checklists), com o período e o formato de cada item. O cliente pode enviar pelo grupo ou por e-mail, conforme sua preferência. Itens marcados "se pertinente" entram conforme o perfil do cliente.', 'Analista de Negócios', 'Manual', 'Após a reunião de onboarding (mesmo dia)', 'P1', 'Lista de coleta enviada no grupo, com período e formato de cada item e os canais aceitos (grupo ou e-mail).', 'Fase0-Prompt-Abertura-Briefing-Estrategico.md', 0.5, 1.5, '{"obj": "Enviar a lista de coleta logo após a reunião.", "ent": ["Checklist de Coleta (BD_Checklists)", "Itens alinhados na reunião"], "passos": ["Selecionar os itens do Checklist de Coleta pertinentes ao perfil do cliente.", "Informar período e formato de cada item.", "Enviar no grupo, indicando que o cliente pode responder pelo grupo ou por e-mail.", "Marcar os itens no Controle por cliente conforme forem chegando (E03-T04)."], "sai": "Lista enviada com período, formato e canais aceitos.", "ferr": ["WhatsApp", "Painel — Controle por cliente"], "cuid": ["Itens \"se pertinente\" entram conforme o perfil do cliente."]}'::jsonb, null),
  ('E02-T04', 'v8.0-pop-20261103', 2, 'Onboarding e Diagnóstico', 'Implementação', 4, 11, 'Construção da apresentação de diagnóstico', 'O GC estrutura a apresentação de onboarding com o diagnóstico inicial, gargalos identificados e proposta de plano. Revisão interna antes da reunião.', 'Gerente de Contas', 'Manual', 'Antes da reunião', 'P1', 'Apresentação revisada e aprovada internamente.', 'Fase0-Prompt-Abertura-Briefing-Estrategico.md', 0.5, 1.5, '{"obj": "Montar a apresentação de diagnóstico inicial.", "ent": ["Formulário", "Briefing Estratégico (Fase 0)", "Arquivos-base do cliente"], "passos": ["Rodar o Prompt de Abertura (Fase 0, Parte B) no Projeto do cliente.", "Revisar as 12 seções do briefing e auditar a Seção 11 (Mapa Claim → Fonte).", "Gerar a apresentação de Onboarding pela skill bmo-onboarding-pptx.", "Revisar internamente antes da reunião."], "sai": "Apresentação revisada e aprovada internamente.", "ferr": ["Claude", "PowerPoint"], "cuid": ["Inconsistência estrutural no PCF durante a calibração → pausar e ir à Fase 1, Prompt A."]}'::jsonb, null),
  ('E02-T05', 'v8.0-pop-20261103', 2, 'Onboarding e Diagnóstico', 'Implementação', 5, 12, 'Reunião de onboarding realizada', 'GC e Analista de Negócios conduzem a reunião: apresentam o diagnóstico, alinham metas e expectativas, definem o plano inicial de ação com o cliente e alinham a lista de dados a coletar (Checklist de Coleta).', 'Gerente de Contas + Analista de Negócios', 'Manual', 'Conforme agenda', 'P1', 'Reunião realizada + apresentação salva.', 'Fase0-Prompt-Abertura-Briefing-Estrategico.md', 0.5, 1.5, '{"obj": "Conduzir a reunião de onboarding.", "ent": ["Apresentação aprovada", "Checklist de Coleta"], "passos": ["Apresentar o diagnóstico e os gargalos identificados.", "Alinhar metas e expectativas.", "Definir o plano inicial de ação com o cliente.", "Alinhar a lista de dados a coletar.", "Garantir gravação (Gemini ou tl;dv) para extração dos itens de ação."], "sai": "Reunião realizada + apresentação salva.", "ferr": ["Google Meet", "Gemini / tl;dv"], "cuid": ["Itens de ação da ata vão para o BMO Tarefas (SOP de Tarefas, seção 4)."]}'::jsonb, null),
  ('E02-T06', 'v8.0-pop-20261103', 2, 'Onboarding e Diagnóstico', 'Implementação', 6, 13, 'Apresentação salva na área do cliente', 'O GC arquiva a apresentação final na área do cliente no sistema, garantindo rastreabilidade e acesso permanente ao material apresentado.', 'Gerente de Contas', 'Manual', 'Dia da reunião', 'P2', 'Arquivo disponível na área do cliente.', 'Fase0-Prompt-Abertura-Briefing-Estrategico.md', 0.5, 1.5, '{"obj": "Arquivar a apresentação na área do cliente.", "ent": ["Apresentação final"], "passos": ["Salvar a versão final na área do cliente no sistema.", "Colar a Seção 12 do briefing nas Instruções do Projeto Claude do cliente."], "sai": "Arquivo disponível na área do cliente.", "ferr": ["Sistema interno", "Claude (Projeto do cliente)"]}'::jsonb, null),
  ('E03-T01', 'v8.0-pop-20261103', 3, 'Coleta e Organização dos Dados', 'Implementação', 1, 14, 'Recebimento e organização dos extratos bancários (OFX)', 'O Analista Financeiro recebe os extratos bancários em OFX dos últimos 6 meses (pelo grupo ou por e-mail), valida a integridade e organiza no sistema interno e na pasta do cliente, por conta e período.', 'Analista Financeiro', 'Manual', 'Assim que recebido', 'P1', 'Extratos OFX dos últimos 6 meses organizados e validados no sistema e na pasta do cliente.', null, 1.5, 2.5, '{"obj": "Receber, validar e organizar os extratos OFX.", "ent": ["OFX de todas as contas PJ, últimos 6 meses"], "passos": ["Receber os OFX pelo grupo ou por e-mail.", "Validar integridade: período completo, todas as contas, arquivos abrindo.", "Organizar por conta e período no sistema interno e na pasta do cliente.", "Marcar \"Recebido\" e \"Validado\" no item 1 do Checklist de Coleta."], "sai": "OFX de 6 meses organizados e validados.", "ferr": ["Sistema interno", "Pasta do cliente"], "cuid": ["Lacuna de IA nesta tarefa: organização do OFX ainda manual."]}'::jsonb, null),
  ('E03-T02', 'v8.0-pop-20261103', 3, 'Coleta e Organização dos Dados', 'Implementação', 2, 15, 'Registro de acessos, taxas de cartão e alíquotas tributárias', 'O Analista de Negócios registra o acesso da BMO ao sistema de gestão do cliente (usuário com perfil que permita ver as informações financeiras e administrativas) e quais módulos o cliente de fato alimenta (agenda, prontuário, financeiro, estoque), as taxas de cartão por bandeira/modalidade e a alíquota de imposto aplicável, confirmada com o contador do cliente.', 'Analista de Negócios', 'Manual', 'Assim que recebido', 'P1', 'Acesso ao sistema de gestão testado + taxas por bandeira/modalidade e alíquotas (confirmadas com o contador) registradas.', null, 1.5, 2.5, '{"obj": "Registrar acesso ao sistema de gestão, taxas de cartão e alíquotas.", "ent": ["Usuário BMO no sistema de gestão", "Taxas por bandeira e modalidade", "Contato do contador"], "passos": ["Testar o acesso com perfil que veja informações financeiras e administrativas.", "Registrar os módulos que o cliente alimenta (agenda, prontuário, financeiro, estoque).", "Registrar taxas por bandeira e modalidade (débito, crédito, parcelado).", "Confirmar regime e alíquota por tipo de receita com o contador."], "sai": "Acesso testado + taxas e alíquotas registradas.", "ferr": ["Sistema de gestão do cliente"], "cuid": ["Liberar o perfil pode levar ~2 semanas e gerar custo de licença — alinhar com o cliente antes de pedir."]}'::jsonb, null),
  ('E03-T03', 'v8.0-pop-20261103', 3, 'Coleta e Organização dos Dados', 'Implementação', 3, 16, 'Recebimento das informações complementares e regras do negócio', 'O Analista de Negócios recebe e organiza na pasta do cliente as informações complementares do Checklist de Coleta: planilhas financeiras (identificação de pagamentos, comprovantes, contas a pagar), DRE ou relatórios gerenciais já existentes, regras do negócio (remuneração, bonificação e comissionamento da equipe, repasses médicos, procedimentos com custo de terceiros) e, se pertinente, material de identidade visual e plano de negócios. Indica a etapa do SOP que vai usar cada item.', 'Analista de Negócios', 'Manual', 'Assim que recebido', 'P2', 'Itens recebidos organizados na pasta do cliente, com a etapa de destino identificada.', null, 1.5, 2.5, '{"obj": "Organizar as informações complementares e as regras do negócio.", "ent": ["Planilhas financeiras", "DRE existente", "Regras de remuneração, comissão e repasse", "Procedimentos com custo de terceiros", "Identidade visual e plano de negócios (se pertinente)"], "passos": ["Salvar cada item na pasta do cliente.", "Indicar a etapa do SOP que usa cada item (E04, E06, E07, E08, E10, E12).", "Atualizar o Checklist de Coleta."], "sai": "Itens organizados com a etapa de destino identificada.", "ferr": ["Pasta do cliente", "Painel — Controle por cliente"]}'::jsonb, null),
  ('E03-T04', 'v8.0-pop-20261103', 3, 'Coleta e Organização dos Dados', 'Implementação', 4, 17, 'Acompanhamento das pendências da coleta', 'O Analista de Negócios atualiza o Checklist de Coleta e cobra no grupo do cliente, toda semana, os itens ainda pendentes, até que todos os obrigatórios sejam recebidos e validados. No caso observado, a cobrança foi feita no report semanal da implementação (ver PV-10).', 'Analista de Negócios', 'Recorrente', 'Semanal, até concluir a coleta', 'P1', 'Checklist de Coleta com todos os itens obrigatórios recebidos e validados.', null, 1.5, 2.5, '{"obj": "Cobrar semanalmente as pendências da coleta.", "ent": ["Checklist de Coleta do cliente"], "passos": ["Toda semana, revisar o Checklist de Coleta no Controle por cliente.", "Listar os itens obrigatórios pendentes.", "Cobrar no grupo do cliente.", "Repetir até todos os obrigatórios estarem recebidos e validados."], "sai": "Todos os itens obrigatórios recebidos e validados.", "ferr": ["Painel — Controle por cliente", "WhatsApp"], "cuid": ["Regra: item concluído só com os dois checks (Recebido e Validado)."], "pend": ["Canal da cobrança no report semanal de implementação a decidir (PV-10)."]}'::jsonb, '[{"id": "CHK-E03-T04-01", "item": "Extratos bancários de todas as contas PJ", "obrig": "Obrigatório", "uso": "Organização do OFX (E03-T01) e conciliação retroativa (E04-T03)", "periodo": "OFX · últimos 6 meses", "resp": "Analista Financeiro", "l1": "Recebido", "l2": "Validado"}, {"id": "CHK-E03-T04-02", "item": "Planilhas financeiras (identificação de pagamentos, comprovantes, contas a pagar e a receber)", "obrig": "Se houver", "uso": "Conciliação e classificação (E04)", "periodo": "Excel ou export do sistema", "resp": "Analista Financeiro", "l1": "Recebido", "l2": "Validado"}, {"id": "CHK-E03-T04-03", "item": "Acesso ao sistema de gestão do cliente (usuário BMO)", "obrig": "Obrigatório", "uso": "Registro de acessos (E03-T02) e base de vendas (E05)", "periodo": "Perfil com acesso financeiro