  ('E04-T01', 'v8.0-pop-20261103', 4, 'BD_Financeiro', 'Implementação', 1, 18, 'Reunião financeira com o cliente', 'O AF conduz a reunião de parametrização: alinha o plano de contas no Conta Azul, a integração bancária e a estrutura de custos da clínica.', 'Analista Financeiro', 'Manual', 'Após onboarding', 'P1', 'Reunião realizada + parametrização iniciada.', null, 1.75, 4.0, '{"obj": "Conduzir a reunião de parametrização financeira.", "ent": ["OFX organizado", "Estrutura de custos"], "passos": ["Agendar \"[Cliente] & BMO <> Reunião Financeira\".", "Alinhar o plano de contas no ContaAzul.", "Alinhar a integração bancária e a estrutura de custos.", "Registrar decisões e itens de ação."], "sai": "Reunião realizada + parametrização iniciada.", "ferr": ["Google Meet", "ContaAzul"]}'::jsonb, null),
  ('E04-T02', 'v8.0-pop-20261103', 4, 'BD_Financeiro', 'Implementação', 2, 19, 'Parametrização do Conta Azul + integração bancária', 'O AF configura o plano de contas, as categorias e ativa a integração bancária automática no Conta Azul. Testa o fluxo de importação.', 'Analista Financeiro', 'Manual', 'Após reunião', 'P1', 'Conta Azul parametrizado e integração ativa.', null, 1.75, 4.0, '{"obj": "Parametrizar o ContaAzul e ativar a integração bancária.", "ent": ["Plano de contas alinhado"], "passos": ["Configurar plano de contas e categorias.", "Ativar a integração bancária automática.", "Testar o fluxo de importação com um extrato recente."], "sai": "ContaAzul parametrizado e integração ativa.", "ferr": ["ContaAzul"]}'::jsonb, null),
  ('E04-T03', 'v8.0-pop-20261103', 4, 'BD_Financeiro', 'Implementação', 3, 20, 'Conciliação bancária retroativa (mínimo 3 meses)', 'O AF concilia os últimos 3 meses de movimentações bancárias, categorizando cada lançamento. Base indispensável para a DRE retroativa.', 'Analista Financeiro', 'Manual', 'Contínuo', 'P1', 'Conciliação de 3 meses concluída sem inconsistências.', null, 1.75, 4.0, '{"obj": "Conciliar no mínimo 3 meses retroativos.", "ent": ["Extratos OFX", "ContaAzul parametrizado"], "passos": ["Importar os 3 meses mais recentes.", "Categorizar cada lançamento.", "Separar os não identificados para a planilha da E04-T04.", "Fechar cada mês sem inconsistências."], "sai": "Conciliação de 3 meses sem inconsistências.", "ferr": ["ContaAzul"], "cuid": ["Base indispensável para a DRE retroativa (Etapa 7)."]}'::jsonb, null),
  ('E04-T04', 'v8.0-pop-20261103', 4, 'BD_Financeiro', 'Implementação', 4, 21, 'Envio de planilha de movimentações não identificadas', 'Durante a conciliação, o AF consolida as movimentações sem identificação em planilha padrão e envia ao cliente para classificação.', 'Analista Financeiro', 'Recorrente', 'Durante conciliação', 'P2', 'Planilha enviada e resposta registrada.', null, 1.75, 4.0, '{"obj": "Enviar a planilha de movimentações não identificadas.", "ent": ["Lançamentos sem identificação"], "passos": ["Consolidar data, valor e histórico bancário de cada movimentação.", "Enviar ao cliente para classificação.", "Registrar a resposta e reclassificar no ContaAzul."], "sai": "Planilha enviada e resposta registrada.", "ferr": ["ContaAzul", "Excel"], "pend": ["Modelo padrão da planilha não localizado no Projeto."]}'::jsonb, null),
  ('E04-T05', 'v8.0-pop-20261103', 4, 'BD_Financeiro', 'Implementação', 5, 22, 'Cobrança recorrente ao cliente para identificar movimentações', 'O AF acompanha semanalmente o retorno do cliente sobre as movimentações pendentes, mantendo follow-up ativo até a classificação completa.', 'Analista Financeiro', 'Recorrente', 'Semanal', 'P2', 'Movimentações identificadas ou follow-up ativo.', null, 1.75, 4.0, '{"obj": "Fazer follow-up semanal das movimentações pendentes.", "ent": ["Planilha enviada"], "passos": ["Toda semana, conferir o que o cliente já respondeu.", "Cobrar o restante no grupo.", "Encerrar quando todas estiverem classificadas."], "sai": "Movimentações identificadas ou follow-up ativo.", "ferr": ["WhatsApp", "ContaAzul"]}'::jsonb, null),
  ('E05-T01', 'v8.0-pop-20261103', 5, 'BD_Vendas', 'Implementação', 1, 23, 'Verificação do uso e preenchimento correto do sistema', 'O AN audita o sistema de vendas/agendamento do cliente: verifica se procedimentos, valores e status estão sendo lançados corretamente.', 'Analista de Negócios', 'Manual', 'Após onboarding', 'P1', 'Sistema validado e em uso correto.', 'Fase4-Comercial-Calendario-Vendas.md (Prompt 3)', 1.5, 3.5, '{"obj": "Auditar o uso do sistema de vendas/agendamento.", "ent": ["Acesso ao sistema", "Contato de quem lança"], "passos": ["Conferir se procedimentos, valores e status estão sendo lançados.", "Comparar uma amostra com o faturamento do período.", "Registrar falhas de preenchimento."], "sai": "Sistema validado e em uso correto.", "ferr": ["Sistema de gestão do cliente"], "cuid": ["Se o cliente usa o sistema só para prontuário, a base de vendas sai de planilhas (item 16 do Checklist)."]}'::jsonb, null),
  ('E05-T02', 'v8.0-pop-20261103', 5, 'BD_Vendas', 'Implementação', 2, 24, 'Treinamento da secretária (se necessário)', 'Caso a auditoria identifique lançamentos incorretos, o AN treina a equipe da clínica no preenchimento padrão do sistema.', 'Analista de Negócios', 'Manual', 'Após verificação', 'P2', 'Treinamento realizado e registrado.', 'Fase4-Comercial-Calendario-Vendas.md (Prompt 3)', 1.5, 3.5, '{"obj": "Treinar a equipe no preenchimento padrão.", "ent": ["Falhas registradas na auditoria"], "passos": ["Agendar o treinamento com quem lança as vendas.", "Demonstrar o preenchimento correto.", "Gravar o treinamento.", "Validar os lançamentos da semana seguinte."], "sai": "Treinamento realizado e registrado.", "ferr": ["Google Meet"], "cuid": ["Padrão validado: treinamento gravado + checklist semanal de validação."]}'::jsonb, null),
  ('E05-T03', 'v8.0-pop-20261103', 5, 'BD_Vendas', 'Implementação', 3, 25, 'Criação do acesso secundário para a BMO', 'O AN solicita/cria um acesso próprio da BMO no sistema do cliente, permitindo extração de dados sem depender da equipe da clínica.', 'Analista de Negócios', 'Manual', 'Após verificação', 'P1', 'Acesso BMO criado e testado.', 'Fase4-Comercial-Calendario-Vendas.md (Prompt 3)', 1.5, 3.5, '{"obj": "Criar o acesso secundário da BMO.", "ent": ["Aprovação do cliente"], "passos": ["Solicitar o usuário BMO no sistema do cliente.", "Testar a extração dos dados de vendas.", "Registrar o acesso no cadastro."], "sai": "Acesso BMO criado e testado.", "ferr": ["Sistema de gestão do cliente"], "cuid": ["Mesmo cuidado da E03-T02: possível custo de licença."]}'::jsonb, null),
  ('E05-T04', 'v8.0-pop-20261103', 5, 'BD_Vendas', 'Implementação', 4, 26, 'Atualização da base de vendas', 'O AN extrai e atualiza diariamente a base de vendas no sistema interno, garantindo dados frescos para reports, BI e análises.', 'Analista de Negócios', 'Recorrente', 'Diário', 'P1', 'Base de vendas atualizada e sem inconsistências.', 'Fase4-Comercial-Calendario-Vendas.md (Prompt 3)', 1.5, 3.5, '{"obj": "Atualizar diariamente o BD_Vendas.", "ent": ["Acesso BMO"], "passos": ["Extrair as vendas do dia anterior.", "Atualizar o BD_Vendas no sistema interno.", "Conferir inconsistências (valores zerados, procedimentos sem cadastro)."], "sai": "BD_Vendas atualizado e sem inconsistências.", "ferr": ["Sistema de gestão do cliente", "Sistema interno"], "cuid": ["⚠️ DIVERGÊNCIA de responsável: aqui é o Analista de Negócios; na E11-T01 o BD_Vendas é atualizado pelo Analista Financeiro."]}'::jsonb, null),
  ('E06-T01', 'v8.0-pop-20261103', 6, 'BD_Cunt', 'Implementação', 1, 27, 'Solicitação de orçamentos e NFs de compras dos últimos meses', 'O AN solicita ao cliente as notas fiscais de compras e orçamentos recentes de insumos — matéria-prima do custo unitário por procedimento.', 'Analista de Negócios', 'Manual', 'Após onboarding', 'P1', 'Documentos recebidos e arquivados.', null, 2.0, 4.5, '{"obj": "Solicitar NFs e orçamentos de insumos.", "ent": ["Lista de procedimentos"], "passos": ["Conferir se o item 7 do Checklist de Coleta já foi recebido.", "Solicitar só o que faltar.", "Arquivar NFs e orçamentos na pasta do cliente."], "sai": "Documentos recebidos e arquivados.", "ferr": ["Pasta do cliente"], "cuid": ["Evitar pedir duas vezes: o item já consta no Checklist de Coleta (E03)."]}'::jsonb, null),
