  ('E12-T04', 'v8.0-pop-20261103', 12, 'Planejamento Financeiro Mensal', 'Gestão Contínua', 4, 63, 'Construção da apresentação de resultado mensal com custos provisionados', 'O AN estrutura a apresentação do resultado do mês com custos provisionados — material da reunião mensal.', 'Analista de Negócios', 'Recorrente', 'Antes da reunião', 'P1', 'Apresentação construída e revisada.', 'Acompanhamento mensal (preso a cliente específico)', 10.0, 12.0, '{"obj": "Montar a apresentação do resultado com custos provisionados.", "ent": ["PCF do mês"], "passos": ["Rodar a leitura mensal Realizado × Planejado.", "Destacar desvios, pontos positivos e de atenção.", "Montar a apresentação."], "sai": "Apresentação revisada.", "ferr": ["Claude", "PowerPoint"]}'::jsonb, null),
  ('E12-T05', 'v8.0-pop-20261103', 12, 'Planejamento Financeiro Mensal', 'Gestão Contínua', 5, 64, 'Agendamento da reunião mensal', 'O GC agenda a reunião de resultado com o decisor no início do mês, garantindo a cadência do rito mensal.', 'Gerente de Contas', 'Recorrente', 'Início do mês', 'P1', 'Reunião agendada e confirmada.', 'Acompanhamento mensal (preso a cliente específico)', 10.0, 12.0, '{"obj": "Agendar a reunião mensal.", "ent": ["Apresentação"], "passos": ["Agendar no início do mês com o decisor.", "Confirmar presença."], "sai": "Reunião agendada.", "ferr": ["Google Calendar"]}'::jsonb, null),
  ('E12-T06', 'v8.0-pop-20261103', 12, 'Planejamento Financeiro Mensal', 'Gestão Contínua', 6, 65, 'Reunião de resultado realizada', 'O GC apresenta o resultado do mês, analisa desvios em relação à meta e valida o plano de ação dos próximos 30 dias.', 'Gerente de Contas', 'Recorrente', '1ª semana do mês', 'P1', 'Reunião realizada e registrada.', 'Acompanhamento mensal (preso a cliente específico)', 10.0, 12.0, '{"obj": "Conduzir a reunião de resultado.", "ent": ["Apresentação"], "passos": ["Apresentar resultado e desvios em relação à meta.", "Validar o plano de ação dos próximos 30 dias.", "Gravar e registrar."], "sai": "Reunião realizada e registrada.", "ferr": ["Google Meet"]}'::jsonb, null),
  ('E12-T07', 'v8.0-pop-20261103', 12, 'Planejamento Financeiro Mensal', 'Gestão Contínua', 7, 66, 'Consolidação da DRE com custos fechados', 'O AN consolida a DRE definitiva do mês com todos os custos fechados (substituindo os provisionados). Prazo institucional: dia 15.', 'Analista de Negócios', 'Recorrente', 'Até dia 15', 'P1', 'DRE consolidada e sem pendências.', 'Acompanhamento mensal (preso a cliente específico)', 10.0, 12.0, '{"obj": "Consolidar a DRE com custos fechados (até dia 15).", "ent": ["Custos fechados"], "passos": ["Substituir provisionados por realizados.", "Rodar o CHECK do Pilar 5 e atualizar Saúde Financeira e Estrutura Econômica (sem recalcular o IDE)."], "sai": "DRE consolidada sem pendências.", "ferr": ["PCF"]}'::jsonb, null),
  ('E12-T08', 'v8.0-pop-20261103', 12, 'Planejamento Financeiro Mensal', 'Gestão Contínua', 8, 67, 'Construção da apresentação da DRE consolidada', 'O AN monta a apresentação comparativa: DRE financeira vs. gerencial e destrinchamento de custos do mês fechado.', 'Analista de Negócios', 'Recorrente', 'Até dia 15', 'P1', 'Apresentação construída e revisada.', 'Acompanhamento mensal (preso a cliente específico)', 10.0, 12.0, '{"obj": "Montar a apresentação da DRE consolidada.", "ent": ["DRE consolidada"], "passos": ["Comparar DRE Financeira × DRE Gerencial.", "Destrinchar custos do mês fechado.", "Anexar 1 página do CHECK do Pilar 5."], "sai": "Apresentação revisada.", "ferr": ["PowerPoint"]}'::jsonb, null),
  ('E12-T09', 'v8.0-pop-20261103', 12, 'Planejamento Financeiro Mensal', 'Gestão Contínua', 9, 68, 'Envio da DRE consolidada + sinalização no grupo do WhatsApp', 'O AN envia a DRE consolidada ao cliente e sinaliza no grupo — fechamento formal do ciclo financeiro do mês.', 'Analista de Negócios', 'Recorrente', 'Dia 15', 'P1', 'DRE enviada e sinalizada no grupo.', 'Acompanhamento mensal (preso a cliente específico)', 10.0, 12.0, '{"obj": "Enviar a DRE consolidada e sinalizar no grupo (dia 15).", "ent": ["Apresentação"], "passos": ["Enviar a DRE consolidada.", "Sinalizar no grupo do WhatsApp."], "sai": "DRE enviada e sinalizada.", "ferr": ["WhatsApp"]}'::jsonb, null),
  ('E12-T10', 'v8.0-pop-20261103', 12, 'Planejamento Financeiro Mensal', 'Gestão Contínua', 10, 69, 'DRE e apresentação salvas na área do cliente', 'O AN arquiva a DRE consolidada e a apresentação na área do cliente — rastreabilidade completa do mês.', 'Analista de Negócios', 'Recorrente', 'Dia 15', 'P2', 'Arquivos disponíveis na área do cliente.', 'Acompanhamento mensal (preso a cliente específico)', 10.0, 12.0, '{"obj": "Arquivar DRE e apresentação (dia 15).", "ent": ["Arquivos finais"], "passos": ["Salvar na área do cliente.", "Atualizar o PCF no Projeto Claude do cliente."], "sai": "Arquivos disponíveis.", "ferr": ["Sistema interno"]}'::jsonb, null),
  ('E13-T01', 'v8.0-pop-20261103', 13, 'Gestão de Riscos', 'Gestão Contínua', 1, 70, 'Preenchimento semanal da planilha de gestão de riscos', 'O GC atualiza semanalmente a planilha de riscos da carteira: engajamento, uso de produto e resultado de cada cliente (Health Score).', 'Gerente de Contas', 'Recorrente', 'Toda semana', 'P1', 'Planilha preenchida e atualizada.', null, 10.0, 12.0, '{"obj": "Atualizar a planilha de riscos da carteira.", "ent": ["Planilha de riscos", "Atas, WhatsApp e reports da semana"], "passos": ["Atualizar \"Últ. contato decisor\" somente com mensagem do próprio decisor.", "Preencher Engajamento, uso de Pricer/BI/DRE/ERP, situação financeira, MRR, tendência e objetivo.", "Recalcular Score e nível de risco após qualquer reordenação.", "Ordenar por Fase → Score decrescente."], "sai": "Planilha preenchida e atualizada.", "ferr": ["Planilha de Gestão de Riscos", "Supabase (bmo_risk_snapshots)"], "cuid": ["Contato de apoio ou de membro BMO não conta como contato do decisor.", "Cliente em churn: Hist. churn = Sim, Tendência = Caindo, Atingindo objetivo = Não."]}'::jsonb, null),
  ('E13-T02', 'v8.0-pop-20261103', 13, 'Gestão de Riscos', 'Gestão Contínua', 2, 71, 'Reunião interna de revisão de riscos', 'GC e Diretor revisam a carteira na reunião semanal: classificam riscos, identificam clientes críticos e priorizam ações.', 'GC + Diretor', 'Recorrente', 'Toda quarta ou quinta', 'P1', 'Reunião realizada e riscos classificados.', null, 10.0, 12.0, '{"obj": "Revisar os riscos em reunião interna (quarta ou quinta).", "ent": ["Planilha atualizada"], "passos": ["Revisar a carteira com o Diretor.", "Classificar riscos e identificar críticos.", "Priorizar ações."], "sai": "Riscos classificados.", "ferr": ["Google Meet"]}'::jsonb, null),
  ('E13-T03', 'v8.0-pop-20261103', 13, 'Gestão de Riscos', 'Gestão Contínua', 3, 72, 'Definição e registro do plano de ação para clientes em risco', 'Para cada cliente classificado em risco, o GC define ação de contenção com owner e prazo, registrada no sistema.', 'Gerente de Contas', 'Manual', 'Após reunião', 'P1', 'Plano de ação registrado com owner e prazo.', null, 10.0, 12.0, '{"obj": "Definir e registrar o plano de ação para clientes em risco.", "ent": ["Clientes classificados em risco"], "passos": ["Definir ação de contenção ligada a um entregável BMO (DRE, DFC, preço, indicadores, planejamento).", "Especificar o mecanismo, não só a intenção.", "Registrar com owner e prazo na coluna Plano de ação."], "sai": "Plano registrado com owner e prazo.", "ferr": ["Planilha de riscos", "BMO Tarefas"], "cuid": ["Ações alinhadas ao cliente, nunca tarefas internas da BMO."]}'::jsonb, null),
  ('E13-T04', 'v8.0-pop-20261103', 13, 'Gestão de Riscos', 'Gestão Contínua', 4, 73, 'Acompanhamento do plano de ação com o squad', 'O GC acompanha a execução dos planos de contenção junto ao squad até a reversão do risco ou decisão de encerramento.', 'Gerente de Contas', 'Manual', 'Contínuo', 'P2', 'Plano em execução e progresso registrado.', null, 10.0, 12.0, '{"obj": "Acompanhar o plano de contenção com o squad.", "ent": ["Planos registrados"], "passos": ["Acompanhar a execução semanal.", "Registrar o progresso.", "Escalar quando não houver reversão."], "sai": "Plano em execução com progresso registrado.", "ferr": ["BMO Tarefas"]}'::jsonb, null),
  ('E14-T01', 'v8.0-pop-20261103', 14, 'Encerramento / Expansão', 'Gestão Contínua', 1, 74, 'Revisão e handoff CRM', 'Ao encerrar o contrato (ou abrir expansão), o GC revisa o ciclo completo do cliente e executa o handoff para o CRM com o histórico documentado.', 'Gerente de Contas', 'Manual', 'Ao encerrar contrato', 'P1', 'Handoff registrado e CRM atualizado.', null, 11.0, 12.0, '{"obj": "Revisar o ciclo e fazer o handoff para o CRM.", "ent": ["Histórico completo do cliente", "Mensagem de cancelamento ou de expansão"], "passos": ["Revisar o ciclo: entrada, diagnóstico, entregas, evolução.", "Em churn: produzir o Relatório de Churn nas 6 seções, com a citação literal da mensagem de cancelamento.", "Pedir ao GC as Observações Gerais (seção 6) antes de finalizar.", "Atualizar o CRM e registrar o handoff."], "sai": "Handoff registrado e CRM atualizado.", "ferr": ["CRM", "Word / PDF"], "cuid": ["A seção 6 nunca é gerada por especulação — vem do GC."]}'::jsonb, null)
