-- Carga do catálogo do SOP (Painel SOP v8, v8.0-pop-20261103) e do cadastro de clientes.
-- Idempotente: pode rodar de novo para atualizar o catálogo sem duplicar nem apagar ajustes feitos no app.
on conflict (id) do update set versao = excluded.versao, etapa_num = excluded.etapa_num, etapa_nome = excluded.etapa_nome,
  workflow = excluded.workflow, ordem = excluded.ordem, sequencia = excluded.sequencia, tarefa = excluded.tarefa,
  descricao = excluded.descricao, papel_responsavel = excluded.papel_responsavel, tipo = excluded.tipo,
  prazo_padrao = excluded.prazo_padrao, prioridade = excluded.prioridade, gate = excluded.gate,
  skill_vinculada = excluded.skill_vinculada, sem_ini = excluded.sem_ini, sem_fim = excluded.sem_fim,
  pop = excluded.pop, checklist = excluded.checklist, ativo = true;

-- 21 clientes da carteira atual + 6 que saíram da carteira (Churn), para o histórico deles continuar ligado.
-- Segmento: fase em bmo_risk_snapshots de 29/07/2026 (12 clientes); 9 a definir pela sincronização com o Sistema Interno.
-- Churn confirmado em 29/07 para Evidence e Leandro Barreto; Calvet, Rached, Luiz Felipe e Gustavo Kobayashi a confirmar.
on conflict (id) do update set
  nome     = excluded.nome,
  grafias  = array(select distinct unnest(public.bmo_clientes.grafias || excluded.grafias) order by 1),  -- soma, não substitui
  segmento = coalesce(public.bmo_clientes.segmento, excluded.segmento),                                   -- não sobrescreve ajuste feito
  updated_at = now();
